def align_to_max_color(grid):
    """Move each object vertically so all tops align with the top of the object with the highest color."""
    g=[r[:] for r in grid]
    objs=objects(g)
    target=min(i for c,cells in objs if c==max(c for c,_ in objs) for i,_ in cells)
    for col,cells in objs:
        top=min(i for i,_ in cells)
        for i,j in cells: g[i][j]=0
        for i,j in cells: g[i-top+target][j]=col
    return g

